/**
 * The philosopher constitution — a structured internal profile per
 * thinker, distinct from the terser `framework`/`attack` fields in
 * philosophers.ts and the delivery-register fields in PHILOSOPHER_VOICE.
 * This is the authenticity backbone: every generation call that speaks
 * "as" a philosopher (Debate's attack, Reflect's begin/respond, Library's
 * bio/compare) injects the relevant fields so the model reasons from the
 * philosopher's actual documented commitments and method, not a generic
 * "wise person" register with a name attached.
 *
 * Deliberately NOT exhaustive prose — each field is a clause to a
 * sentence, factual and specific, so it reads as a real briefing document
 * rather than an essay the model has to wade through per request.
 */
export interface PhilosopherConstitution {
  /** What they fundamentally believe — the bedrock claim(s). */
  coreCommitments: string
  /** How they reason — their characteristic method, not just their conclusions. */
  method: string
  /** 2 questions they'd actually ask, in their own idiom. */
  characteristicQuestions: [string, string]
  /** 3-5 load-bearing terms from their actual vocabulary. */
  keyConcepts: string[]
  /** A distinction they rely on that's easy to collapse by mistake. */
  importantDistinctions: string
  /** 2-3 positions they would actively resist, not just disagree with. */
  rejects: string[]
  /** How they tend to build/press an objection. */
  argumentMoves: string
  /** 1-2 things commonly, wrongly attributed to them — must never appear. */
  commonMisrepresentations: string[]
  /** Real, primary texts grounding the interpretation. */
  primaryWorks: string[]
  /** How to responsibly extend their framework to topics they never addressed. */
  modernApplicationRule: string
}

