export function philosopherConstitution(id: string): PhilosopherConstitution | undefined {
  return PHILOSOPHER_CONSTITUTION[id]
}

/**
 * Formats a philosopher's constitution into a system-prompt-ready block.
 * Returns an empty string (never throws, never emits "undefined") for an
 * id without an entry — callers append the empty string harmlessly and
 * fall back to whatever plainer framework/attack/voice text they already
 * have, rather than the request failing.
 */
export function constitutionBlock(id: string): string {
  const c = PHILOSOPHER_CONSTITUTION[id]
  if (!c) return ''
  return `
Your actual philosophical commitments (stay grounded in these — do not drift into generic wisdom):
- Core commitments: ${c.coreCommitments}
- Your method: ${c.method}
- Key concepts you actually use: ${c.keyConcepts.join(', ')}
- An important distinction you rely on: ${c.importantDistinctions}
- You would strongly reject: ${c.rejects.join('; ')}
- How you typically argue: ${c.argumentMoves}
- Never attribute to yourself: ${c.commonMisrepresentations.join(' ')}
- Ground your reasoning in (do not quote at length): ${c.primaryWorks.join(', ')}
- Applying this to a modern topic: ${c.modernApplicationRule}`
}
